import{_ as a,b as s,c as l,f as e}from"./chunks/framework.86O3EbG5.js";const u=JSON.parse('{"title":"学科的范式奠基与路径依赖","description":"","frontmatter":{"title":"学科的范式奠基与路径依赖","author":"oasis","date":"2026-05-11T00:00:00.000Z","tags":["Date Log"]},"headers":[],"relativePath":"articles/self/1.md","filePath":"articles/self/1.md"}'),r={name:"articles/self/1.md"};function n(o,t,p,c,i,d){return s(),l("div",null,[...t[0]||(t[0]=[e("p",null,"今天借助微信读书中的AI能力，扫了很多书。扫书的过程中，我突然产生了一种绝望：“一个学科创建后，学科的历史发展方向便不会出现颠覆。一旦出现颠覆，要么该学科消失，要么新知识体系建立、新范式崛起。”",-1),e("p",null,"我很好奇有没有人和我的观点相似，通过询问AI后发现，我的思考与托马斯·库恩《科学革命的结构》中的论述一致。这可以归纳为学科的范式奠基与路径依赖。",-1),e("p",null,"学科建立时，核心学者们定义了该领域的研究对象、研究方法、基础概念和假设。一旦这些核心内容被确定，后续研究者的工作将在这个框架下展开。",-1),e("p",null,"而且学科知识的进步依赖同行评议和社会权力的认同。这里是否会出现一种悖论：当如哥白尼或达尔文这样的人出现时，群体的打压会阻碍科学进步？",-1),e("p",null,"从另一个角度看，哥白尼和达尔文是概率的产物。科学的进步是概率性的，并非绝对。可悲。人类找到真理的时间是无法预测的。",-1)])])}const _=a(r,[["render",n]]);export{u as __pageData,_ as default};
